  'faq2-a' => 'सीधे तौर पर नहीं, क्योंकि स्कैन की गई पीडीएफ़ में टेक्स्ट के बजाय छवियां होती हैं। स्कैन की गई छवियों को पढ़ने योग्य पाठ में बदलने के लिए पीडीएफ को पहले ओसीआर से गुजरना होगा। कुछ AI उपकरण इसे स्वचालित रूप से संभालते हैं। यदि आपका नहीं है, तो पहले OCR टूल का उपयोग करके स्कैन की गई पीडीएफ को टेक्स्ट-आधारित पीडीएफ में परिवर्तित करने से संक्षेपण सक्षम हो जाता है।',
  'faq3-q' => 'क्या गोपनीय दस्तावेज़ों को AI सारांश उपकरण पर अपलोड करना सुरक्षित है?',
  'faq3-a' => 'यह सेवा की गोपनीयता नीति पर निर्भर करता है। PDFTools एक घंटे के बाद सभी अपलोड की गई फ़ाइलों को हटा देता है और AI मॉडल के प्रशिक्षण के लिए दस्तावेज़ सामग्री का उपयोग नहीं करता है। अत्यधिक गोपनीय दस्तावेज़ों के लिए, अपलोड करने से पहले किसी भी टूल की गोपनीयता नीति की जाँच करें। ऑनलाइन टूल के साथ फ़ाइल सुरक्षा पर अधिक जानकारी के लिए, __SAFETY_GUIDE_LINK__ पर मार्गदर्शिका देखें।',
  'faq4-q' => 'क्या AI अंग्रेजी के अलावा अन्य भाषाओं में PDF का सारांश प्रस्तुत कर सकता है?',
  'faq4-a' => 'अधिकांश प्रमुख एआई मॉडल, जिनमें चैटजीपीटी और गूगल जेमिनी शामिल हैं, कई भाषाओं में सारांश का समर्थन करते हैं। अंग्रेजी दस्तावेज़ों और प्रमुख यूरोपीय भाषाओं के लिए गुणवत्ता उच्चतम होती है, और कम आम भाषाओं के लिए कुछ हद तक कम होती है।',
);
